class Solution:
    def longestValidParentheses(self, s: str) -> int:
        stack = [-1]
        best = 0

        for i in range(len(s)):
            if s[i] == '(':
                stack.append(i)
            elif stack:
                idx = stack.pop()
                if not stack:
                    stack.append(i)
                else:
                    cur_len = i - stack[-1]
                    best = max(best, cur_len)

        return best
